python:get all jobs updated after januar.code:
import requests
import json
import urllib.parse

filter_obj = {
    "must": [
        {
            "range": {
                "date_updated": {
                    "gte": 1672531200
                }
            }
        }
    ]
}

filter_str = urllib.parse.quote(json.dumps(filter_obj))

url = "https://app.jobnimbus.com/api1/jobs"
headers = {
    "Authorization": "bearer YOUR_API_KEY"
}
params = {
    "filter": filter_str
}

response = requests.get(url, headers=headers, params=params)

if response.status_code == 200:
    print(response.json())
else:
    print("Error:", response.status_code)
    print(response.text)

